"""Модель світу для модуля robot (Python/tkinter)."""

NORTH = 0
EAST = 1
SOUTH = 2
WEST = 3

DX = [0, 1, 0, -1]
DY = [-1, 0, 1, 0]

DIR_NAMES_OUT = ["north", "east", "south", "west"]
DIR_NAMES_IN = {
    "up": NORTH, "north": NORTH,
    "right": EAST, "east": EAST,
    "down": SOUTH, "south": SOUTH,
    "left": WEST, "west": WEST,
}


def section(lines, name):
    from_idx = -1
    to_idx = -1
    for i, line in enumerate(lines):
        if line.startswith(name):
            from_idx = i + 1
            continue
        if from_idx > 0 and line.strip() == "":
            to_idx = i
            break
    if from_idx < 0:
        return ""
    if to_idx < 0:
        to_idx = len(lines)
    return "\n".join(lines[from_idx:to_idx])


def parse_direction(text):
    import re
    m = re.search(r"[A-Za-z]+", str(text or ""))
    if not m:
        return NORTH
    d = DIR_NAMES_IN.get(m.group(0).lower())
    return NORTH if d is None else d


def parse_extras(text):
    import re
    out = []
    for m in re.finditer(r"(\w+)@(\d+),(\d+)", text):
        out.append({"name": m.group(1), "x": int(m.group(2)), "y": int(m.group(3))})
    return out


def parse_strokes(text):
    import re
    out = []
    for m in re.finditer(r"\(([wb]),([.\-|]),(-?\d+),(-?\d+)\)", text):
        out.append({"color": m.group(1), "type": m.group(2),
                    "x": int(m.group(3)), "y": int(m.group(4))})
    return out


def stroke_key(s):
    return s["color"] + s["type"] + str(s["x"]) + "," + str(s["y"])


class World:
    def __init__(self, map_text=None):
        self.rows = []
        self.width = 0
        self.height = 0
        self.start = {"x": 0, "y": 0}
        self.start_dir = NORTH
        self.extras = []
        self.strokes = []
        self.stroke_index = {}
        self.painted = []
        self.paint_color = []
        self.painted_list = []
        self.energons = []
        self.collect = 0
        self.total_energons = 0
        self.robot = {
            "x": 0, "y": 0, "dir": NORTH, "paint_mode": "off",
            "gripper": "rest", "out_of_bounds": False, "bumped": False,
        }
        if map_text:
            self.load(map_text)

    def load(self, text):
        raw = str(text).split("\n")
        # нормалізуємо переноси \r
        raw = [r.rstrip("\r") for r in raw]
        if raw and raw[-1] == "":
            raw.pop()
        lines = []
        for r in raw:
            if r.startswith("#"):
                continue
            lines.append(r)

        rows = []
        for i, line in enumerate(lines):
            if line.startswith("map:"):
                for j in range(i + 1, len(lines)):
                    rows.append(lines[j])
                break

        width = 0
        for r in rows:
            width = max(width, len(r))
        height = len(rows)

        self.extras = parse_extras(section(lines, "extra:"))
        self.strokes = parse_strokes(section(lines, "paint:"))
        self.start_dir = parse_direction(section(lines, "direction:"))

        self.rows = rows
        self.width = width
        self.height = height
        self.energons = []
        self.collect = 0
        self.painted = []
        self.paint_color = []
        self.painted_list = []
        self.start = {"x": 0, "y": 0}
        self.stroke_index = {}

        for y in range(height):
            self.painted.append([False] * width)
            self.paint_color.append([None] * width)

        for y, row in enumerate(rows):
            for x in range(len(row)):
                ch = row[x]
                if ch == "@":
                    self.start = {"x": x, "y": y}
                elif ch == "*":
                    self.energons.append({"x": x, "y": y})

        self.total_energons = len(self.energons)

        for s in list(self.strokes):
            self.apply_stroke(s)
            self.stroke_index[stroke_key(s)] = s

        self.robot = {
            "x": self.start["x"], "y": self.start["y"], "dir": self.start_dir,
            "paint_mode": "off", "bumped": False, "gripper": "rest",
            "out_of_bounds": False,
        }

    def apply_stroke(self, stroke):
        color = stroke["color"]
        t = stroke["type"]
        x, y = stroke["x"], stroke["y"]
        if t == ".":
            self.set_paint(x, y, color)
        elif t == "-":
            self.set_paint(x, y, color)
            self.set_paint(x + 1, y, color)
        elif t == "|":
            self.set_paint(x, y, color)
            self.set_paint(x, y + 1, color)

    def add_stroke(self, color, typ, x, y):
        stroke = {"color": color, "type": typ, "x": x, "y": y}
        key = stroke_key(stroke)
        old = self.stroke_index.get(key)
        if old is not None:
            # знайти в списку
            for i in range(len(self.strokes) - 1, -1, -1):
                if self.strokes[i] is old:
                    del self.strokes[i]
                    break
        self.strokes.append(stroke)
        self.stroke_index[key] = stroke
        self.apply_stroke(stroke)
        return stroke

    def set_paint(self, x, y, color):
        if y < 0 or y >= len(self.painted):
            return
        row = self.painted[y]
        if x < 0 or x >= len(row):
            return
        if not self.painted[y][x]:
            self.painted[y][x] = True
            self.painted_list.append({"x": x, "y": y})
        self.paint_color[y][x] = color

    def tile_at(self, x, y):
        if y < 0 or y >= len(self.rows):
            return None
        row = self.rows[y]
        if x < 0 or x >= len(row):
            return None
        return row[x]

    def is_out_of_bounds(self, x, y):
        return self.tile_at(x, y) is None

    def is_obstacle(self, x, y):
        ch = self.tile_at(x, y)
        if ch is None:
            return True
        return ("A" <= ch <= "Z")

    def is_energon(self, x, y):
        for e in self.energons:
            if e["x"] == x and e["y"] == y:
                return True
        return False

    def is_painted(self, x, y):
        if y < 0 or y >= len(self.painted):
            return False
        row = self.painted[y]
        if x < 0 or x >= len(row):
            return False
        return bool(self.painted[y][x])

    def paint_color_at(self, x, y):
        if y < 0 or y >= len(self.paint_color):
            return None
        row = self.paint_color[y]
        if x < 0 or x >= len(row):
            return None
        return self.paint_color[y][x]

    def is_white(self, x, y):
        return self.paint_color_at(x, y) == "w"

    def is_black(self, x, y):
        return self.paint_color_at(x, y) == "b"

    def point_in_front(self, x, y, d):
        return {"x": x + DX[d], "y": y + DY[d]}

    def look_at(self, d):
        p = self.point_in_front(self.robot["x"], self.robot["y"], d)
        return {
            "obstacle": self.is_obstacle(p["x"], p["y"]),
            "energon": self.is_energon(p["x"], p["y"]),
            "white": self.is_white(p["x"], p["y"]),
            "black": self.is_black(p["x"], p["y"]),
        }

    def move_forward(self, n):
        moved = 0
        self.robot["bumped"] = False
        self.robot["out_of_bounds"] = False
        for i in range(n):
            p = self.point_in_front(self.robot["x"], self.robot["y"], self.robot["dir"])
            if self.is_out_of_bounds(p["x"], p["y"]):
                self.robot["out_of_bounds"] = True
                self.robot["bumped"] = True
                break
            if self.is_obstacle(p["x"], p["y"]):
                self.robot["bumped"] = True
                break
            from_x, from_y = self.robot["x"], self.robot["y"]
            self.robot["x"] = p["x"]
            self.robot["y"] = p["y"]
            moved += 1
            self.paint_trail(from_x, from_y, p["x"], p["y"])
        return moved

    def move_backward(self, n):
        moved = 0
        self.robot["bumped"] = False
        self.robot["out_of_bounds"] = False
        for i in range(n):
            p = self.point_in_front(self.robot["x"], self.robot["y"], (self.robot["dir"] + 2) % 4)
            if self.is_out_of_bounds(p["x"], p["y"]):
                self.robot["out_of_bounds"] = True
                self.robot["bumped"] = True
                break
            if self.is_obstacle(p["x"], p["y"]):
                self.robot["bumped"] = True
                break
            from_x, from_y = self.robot["x"], self.robot["y"]
            self.robot["x"] = p["x"]
            self.robot["y"] = p["y"]
            moved += 1
            self.paint_trail(from_x, from_y, p["x"], p["y"])
        return moved

    def turn_left(self):
        self.robot["dir"] = (self.robot["dir"] + 3) % 4

    def turn_right(self):
        self.robot["dir"] = (self.robot["dir"] + 1) % 4

    def face_to(self, d):
        self.robot["dir"] = ((d % 4) + 4) % 4

    def paint_under_robot(self):
        if self.robot["paint_mode"] == "off":
            return
        self.add_stroke(self.robot["paint_mode"], ".", self.robot["x"], self.robot["y"])

    def paint_trail(self, from_x, from_y, to_x, to_y):
        if self.robot["paint_mode"] == "off":
            return
        if from_x == to_x and from_y == to_y:
            return
        if from_y == to_y:
            self.add_stroke(self.robot["paint_mode"], "-", min(from_x, to_x), from_y)
        else:
            self.add_stroke(self.robot["paint_mode"], "|", from_x, min(from_y, to_y))

    def set_paint_mode(self, mode):
        prev = self.robot["paint_mode"]
        self.robot["paint_mode"] = mode
        if mode != "off" and mode != prev:
            self.paint_under_robot()

    def clear_paint(self):
        x = self.robot["x"]
        y = self.robot["y"]
        if y >= 0 and y < len(self.painted) and x >= 0 and x < len(self.painted[y]) and self.painted[y][x]:
            self.painted[y][x] = False
            self.paint_color[y][x] = None
            for i in range(len(self.painted_list) - 1, -1, -1):
                if self.painted_list[i]["x"] == x and self.painted_list[i]["y"] == y:
                    del self.painted_list[i]
                    break
            for i in range(len(self.strokes) - 1, -1, -1):
                s = self.strokes[i]
                covers = False
                if s["type"] == "." and s["x"] == x and s["y"] == y:
                    covers = True
                elif s["type"] == "-" and s["y"] == y and (s["x"] == x or s["x"] + 1 == x):
                    covers = True
                elif s["type"] == "|" and s["x"] == x and (s["y"] == y or s["y"] + 1 == y):
                    covers = True
                if covers:
                    key = stroke_key(s)
                    if self.stroke_index.get(key) is s:
                        del self.stroke_index[key]
                    del self.strokes[i]
            return True
        return False

    def pick_up(self):
        p = self.point_in_front(self.robot["x"], self.robot["y"], self.robot["dir"])
        for i, e in enumerate(self.energons):
            if e["x"] == p["x"] and e["y"] == p["y"]:
                del self.energons[i]
                return True
        return False

    def to_map_text(self):
        out = []
        out.append("# generated map")
        out.append("")
        out.append("")
        if self.strokes:
            out.append("paint:")
            line = ""
            for s in self.strokes:
                line += "(" + s["color"] + "," + s["type"] + "," + str(s["x"]) + "," + str(s["y"]) + ")"
                if len(line) > 70:
                    out.append(line)
                    line = ""
            if line:
                out.append(line)
            out.append("")
        if self.extras:
            out.append("extra:")
            for e in self.extras:
                out.append(e["name"] + "@" + str(e["x"]) + "," + str(e["y"]))
            out.append("")
        if self.robot["dir"] != NORTH:
            out.append("direction:")
            out.append(DIR_NAMES_OUT[self.robot["dir"]])
            out.append("")
        out.append("map:")
        for y in range(len(self.rows)):
            chars = list(self.rows[y])
            # pad
            while len(chars) < self.width:
                chars.append(" ")
            if 0 <= self.robot["x"] < len(chars) and self.robot["y"] == y:
                chars[self.robot["x"]] = "@"
            for b in self.energons:
                if b["y"] == y and b["x"] < len(chars):
                    chars[b["x"]] = "*"
            out.append("".join(chars))
        return "\n".join(out) + "\n"

