"""Читання карт користувача (.map) та світів (.world — ZIP-архів із картами).

Формат світу такий самий, як у веб-застосунку: ZIP, у якому лежать файли
карт ``*.map`` і файл ``maps.json`` — JSON-масив імен карт у потрібному
порядку. Якщо ``maps.json`` немає, беруться всі ``*.map`` з архіву
(у природному порядку: map2 перед map10).
"""

import json
import os
import re
import zipfile

MAX_MAP_BYTES = 1024 * 1024      # захист від надто великих файлів / «zip-бомб»
MAX_WORLD_MAPS = 1000


class MapFileError(Exception):
    """Файл карти чи світу неможливо прочитати. Текст — для показу користувачеві."""


def decode_text(data):
    """Байти → текст: UTF-8 (з BOM або без), інакше windows-1251."""
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        return data.decode("cp1251", errors="replace")


def validate_map_text(name, text):
    """Повертає текст помилки або "" (як validateMapFile у веб-версії).

    Правила розбору збігаються з World.load: рядки, що починаються з «#»,
    ігноруються, сітка — усе, що йде після рядка «map:».
    """
    if not str(name).lower().endswith(".map"):
        return "файл не має розширення .map"

    lines = [ln for ln in re.split(r"\r\n|\r|\n", text.lstrip("\ufeff"))
             if not ln.startswith("#")]
    start = None
    for i, ln in enumerate(lines):
        if ln.startswith("map:"):
            start = i
            break
    if start is None:
        return "немає секції map:"

    rows = lines[start + 1:]
    while rows and rows[-1] == "":
        rows.pop()
    if not rows:
        return "порожня карта"

    for row in rows:
        for ch in row:
            if ch in " @*" or "A" <= ch <= "Z":
                continue
            return "недопустимий символ «%s»" % ch
    return ""


def read_map_file(path):
    """Читає один файл карти. Повертає (ім'я файлу, текст)."""
    name = os.path.basename(path)
    try:
        if os.path.getsize(path) > MAX_MAP_BYTES:
            raise MapFileError("%s: файл надто великий" % name)
        with open(path, "rb") as f:
            data = f.read()
    except OSError as e:
        raise MapFileError("Не вдалося прочитати %s: %s" % (name, e))
    text = decode_text(data)
    error = validate_map_text(name, text)
    if error:
        raise MapFileError("%s: %s" % (name, error))
    return name, text


def _natural_key(name):
    return [int(p) if p.isdigit() else p.lower() for p in re.split(r"(\d+)", name)]


def read_world_file(path):
    """Читає світ (ZIP). Повертає (maps, skipped).

    maps    — список {"name": ..., "text": ...} у порядку з maps.json;
    skipped — список рядків «ім'я — причина» для карт, які не вдалося взяти.
    Якщо жодної придатної карти немає — MapFileError.
    """
    wname = os.path.basename(path)
    try:
        zf = zipfile.ZipFile(path)
    except (OSError, zipfile.BadZipFile):
        raise MapFileError("%s: це не архів світу (ZIP)" % wname)

    with zf:
        # ім'я у нижньому регістрі (без папок) → ZipInfo
        entries = {}
        for info in zf.infolist():
            if info.is_dir():
                continue
            base = info.filename.replace("\\", "/").split("/")[-1]
            if base.startswith(".") or base.startswith("__"):
                continue
            entries.setdefault(base.lower(), info)

        names = None
        meta = entries.get("maps.json")
        if meta is not None:
            try:
                data = json.loads(decode_text(zf.read(meta)))
                if not isinstance(data, list):
                    raise ValueError
                names = [str(n) for n in data]
            except (ValueError, KeyError, RuntimeError, zipfile.BadZipFile):
                raise MapFileError("%s: файл maps.json пошкоджено" % wname)
        if names is None:
            names = sorted((i.filename.replace("\\", "/").split("/")[-1]
                            for i in entries.values()
                            if i.filename.lower().endswith(".map")),
                           key=_natural_key)

        maps = []
        skipped = []
        seen = set()
        for raw_name in names[:MAX_WORLD_MAPS]:
            name = raw_name.replace("\\", "/").split("/")[-1]
            key = name.lower()
            if key in seen:
                continue
            seen.add(key)
            info = entries.get(key)
            if info is None:
                skipped.append("%s — немає в архіві" % name)
                continue
            if info.file_size > MAX_MAP_BYTES:
                skipped.append("%s — файл надто великий" % name)
                continue
            try:
                text = decode_text(zf.read(info))
            except (OSError, RuntimeError, zipfile.BadZipFile):
                skipped.append("%s — не вдалося прочитати" % name)
                continue
            error = validate_map_text(name, text)
            if error:
                skipped.append("%s — %s" % (name, error))
                continue
            maps.append({"name": name, "text": text})

    if not maps:
        detail = ("\n" + "\n".join(skipped)) if skipped else ""
        raise MapFileError("%s: у світі немає жодної придатної карти%s" % (wname, detail))
    return maps, skipped

