"""Kodik browser adapter for robot-python 1.0 (upstream model/API, MIT)."""
import json
from js import KodikRobot
from .world import World

class CollisionError(Exception):
    pass

class OutOfBoundsError(Exception):
    pass

_world = None
_speed = 5
_skin = 'desert'
_commands = 0

def _snapshot(label=''):
    w = _world
    KodikRobot.enqueue(json.dumps(dict(rows=w.rows, width=w.width, height=w.height,
        robot=w.robot, energons=w.energons, paint=w.paint_color, collected=w.collect,
        total=w.total_energons, speed=_speed, skin=_skin, label=label)))

def _ensure():
    global _world
    if _world is None:
        load_map_text(str(KodikRobot.mapText()))

def load_map_text(text):
    global _world
    from .files import validate_map_text
    error = validate_map_text('custom.map', text)
    if error:
        raise ValueError(error)
    candidate = World(text)
    if candidate.width * candidate.height > 10000:
        raise ValueError('Карта завелика: максимум 10000 клітинок')
    if sum(row.count('@') for row in candidate.rows) != 1:
        raise ValueError('На карті має бути один старт @')
    _world = candidate
    _snapshot('Старт')

def load_map(path):
    import os
    if not os.path.isfile(path) and os.path.basename(path) == path:
        path = os.path.join(os.path.dirname(__file__), 'maps', path)
    with open(path, encoding='utf-8-sig') as source:
        load_map_text(source.read())

def get_world():
    _ensure()
    return _world

def done():
    _ensure()

mainloop = done

def set_program(code):
    raise NotImplementedError('У Кодику редагуй програму в редакторі та натискай Запустити')

def command(name, *args):
    global _speed, _skin, _commands
    _ensure()
    _commands += 1
    if _commands > 10000:
        raise RuntimeError('Ліміт 10000 команд robot за запуск; перевір умову циклу')
    w = _world
    value = None
    if name in ('forward', 'backward', 'north', 'east', 'south', 'west'):
        steps = int(args[0]) if args else 1
        if steps > 10000:
            raise ValueError('Максимум 10000 кроків')
        if name in ('north', 'east', 'south', 'west'):
            w.face_to(('north', 'east', 'south', 'west').index(name))
            _snapshot(name)
        value = 0
        for _ in range(max(0, steps)):
            moved = w.move_backward(1) if name == 'backward' else w.move_forward(1)
            _snapshot(name)
            if not moved:
                error = OutOfBoundsError if w.robot['out_of_bounds'] else CollisionError
                raise error('Перешкода або край карти біля %s' % (command('position'),))
            value += 1
        return value
    if name == 'left':
        w.turn_left()
    elif name == 'right':
        w.turn_right()
    elif name in ('paintWhite', 'paintBlack', 'stopPainting'):
        w.set_paint_mode({'paintWhite':'w', 'paintBlack':'b', 'stopPainting':'off'}[name])
    elif name == 'clearPaint':
        value = w.clear_paint()
    elif name == 'pickUp':
        value = w.pick_up()
        if value:
            w.collect += 1
    elif 'Is' in name:
        side, kind = name.split('Is')
        direction = (w.robot['dir'] + {'front':0, 'left':-1, 'right':1}[side]) % 4
        seen = w.look_at(direction)
        return not seen['obstacle'] if kind == 'Clear' else seen[kind.lower()]
    elif name == 'position':
        return (w.robot['x'], w.robot['y'])
    elif name == 'direction':
        return ('north', 'east', 'south', 'west')[w.robot['dir']]
    elif name == 'EnergonLeft':
        return len(w.energons)
    elif name == 'EnergonTotal':
        return w.total_energons
    elif name == 'collected':
        return w.collect
    elif name == 'isPainted':
        return w.is_painted(int(args[0]), int(args[1]))
    elif name == 'setSpeed':
        _speed = max(0, min(10, int(args[0])))
        value = _speed
    elif name == 'getSpeed':
        return _speed
    elif name == 'skin':
        value = str(args[0]) if args else 'default'
        if value not in ('default', 'desert', 'grass', 'mind', 'lego'):
            raise ValueError('Невідомий скін: ' + value)
        _skin = value
    else:
        raise NameError(name)
    _snapshot(name)
    return value

_ensure()
